using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad] public static partial class HospitalPatientTransfer {
 const string Request="Temp/HospitalPatientTransfer.request"; const string Out="Temp/HospitalPatientTransfer";
 static HospitalPatientTransfer(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlaying||!File.Exists(Request))return;var cmd=File.ReadAllText(Request).Trim();File.Delete(Request);try{Directory.CreateDirectory(Out);if(cmd=="woundview")RenderPoseOnBed(true,true);else if(cmd=="wound")InstallWound();else if(cmd=="regenerated")ApplyRegenerated();else if(cmd=="audit")Audit();else if(cmd=="apply")Apply();else if(cmd=="validate")ValidateAll();else if(cmd=="render")RenderPatient();else if(cmd=="relax")RelaxPose();else if(cmd=="straight")RelaxPose(true);else if(cmd=="bed")RenderPoseOnBed();else if(cmd=="bedtop")RenderPoseOnBed(true);else throw new Exception("Unknown command "+cmd);}catch(Exception e){File.WriteAllText(Out+"/error.txt",e.ToString());Debug.LogException(e);}}
 static T[] All<T>(Scene s) where T:Component=>s.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<T>(true)).ToArray();
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
 static void Audit(){var paths=new[]{"Assets/Scenes/Hospital_Evaluation.unity","Assets/Scenes/Hospital_Tutorial.unity","Assets/Scenes/Emergency_Decon_Evaluation.unity","Assets/Scenes/Emergency_Decon_Tutorial.unity","Assets/Scenes/Emergency_Decon_Tutorial_Hand.unity"};foreach(var p in paths){var s=EditorSceneManager.OpenPreviewScene(p);try{var report=new System.Collections.Generic.List<string>();foreach(var t in All<Transform>(s).Where(t=>PathOf(t).Contains("Patient")||PathOf(t).Contains("Blood")||PathOf(t).Contains("Wound"))){report.Add(PathOf(t)+" active="+t.gameObject.activeSelf+" pos="+t.position.ToString("F4")+" rot="+t.eulerAngles.ToString("F2")+" scale="+t.lossyScale.ToString("F4")+" comps="+string.Join(",",t.GetComponents<Component>().Select(c=>c?c.GetType().Name:"MISSING")));foreach(var r in t.GetComponents<Renderer>())report.Add(" RENDER "+r.bounds+" materials="+string.Join(",",r.sharedMaterials.Select(m=>m?AssetDatabase.GetAssetPath(m):"null")));foreach(var c in t.GetComponents<Collider>())report.Add(" COLLIDER "+EditorJsonUtility.ToJson(c));}foreach(var c in All<MonoBehaviour>(s).Where(c=>c&&(c.GetType().Name=="EvaluationForceps"||c.GetType().Name=="Forceps")))report.Add(" FORCEPS "+PathOf(c.transform)+" "+EditorJsonUtility.ToJson(c));File.WriteAllLines(Out+"/"+s.name+".txt",report);}finally{EditorSceneManager.ClosePreviewScene(s);}}File.WriteAllText(Out+"/status.txt","AUDIT COMPLETE");}
}




